BEGIN;
DELETE FROM news_slider_translations WHERE slider_id IN (SELECT id FROM news_slider WHERE sort_order>=10);
DELETE FROM news_slider WHERE sort_order>=10;
WITH ins AS (INSERT INTO news_slider (news_date,media_id,sort_order,is_active,created_at,updated_at) VALUES ('2026-06-08',2,10,true,now(),now()),('2026-06-05',2,11,true,now(),now()),('2026-06-03',2,12,true,now(),now()),('2026-06-01',2,13,true,now(),now()) RETURNING id,sort_order)
INSERT INTO news_slider_translations (slider_id,locale,title,description,link) SELECT id,'az',(CASE sort_order WHEN 10 THEN 'Mərkəzi Bank məzənnə siyasətini müzakirə etdi' WHEN 11 THEN 'Yeni ödəniş sistemi istifadəyə verildi' WHEN 12 THEN 'Maliyyə savadlılığı həftəsi keçirildi' WHEN 13 THEN 'Bank sektoru üzrə hesabat dərc olundu' END),(CASE sort_order WHEN 10 THEN 'İdarə Heyətinin iclası' WHEN 11 THEN 'Rəqəmsal ödənişlər' WHEN 12 THEN 'Maarifləndirmə tədbiri' WHEN 13 THEN 'Rüblük icmal' END),'/az/press-releases' FROM ins UNION ALL SELECT id,'en',(CASE sort_order WHEN 10 THEN 'Central Bank discussed exchange rate policy' WHEN 11 THEN 'New payment system launched' WHEN 12 THEN 'Financial literacy week held' WHEN 13 THEN 'Banking sector report published' END),(CASE sort_order WHEN 10 THEN 'Executive Board meeting' WHEN 11 THEN 'Digital payments' WHEN 12 THEN 'Awareness event' WHEN 13 THEN 'Quarterly review' END),'/en/press-releases' FROM ins;
DELETE FROM homepage_publication_translations WHERE publication_id IN (SELECT id FROM homepage_publications WHERE sort_order>=10);
DELETE FROM homepage_publications WHERE sort_order>=10;
WITH ins AS (INSERT INTO homepage_publications (media_id,published_at,sort_order,is_active,created_at,updated_at) VALUES (2,'2026-06-01',10,true,now(),now()),(2,'2026-06-02',11,true,now(),now()),(2,'2026-05-03',12,true,now(),now()),(2,'2026-05-04',13,true,now(),now()),(2,'2026-04-05',14,true,now(),now()) RETURNING id,sort_order)
INSERT INTO homepage_publication_translations (publication_id,locale,title,url) SELECT id,'az',(CASE sort_order WHEN 10 THEN 'Pul siyasəti icmalı — 2026 Q1' WHEN 11 THEN 'İllik hesabat 2025' WHEN 12 THEN 'Maliyyə sabitliyi hesabatı' WHEN 13 THEN 'Statistik bülleten' WHEN 14 THEN 'Tədqiqat: inflyasiya dinamikası' END),'/az/publications' FROM ins UNION ALL SELECT id,'en',(CASE sort_order WHEN 10 THEN 'Monetary Policy Review — 2026 Q1' WHEN 11 THEN 'Annual Report 2025' WHEN 12 THEN 'Financial Stability Report' WHEN 13 THEN 'Statistical Bulletin' WHEN 14 THEN 'Research: inflation dynamics' END),'/en/publications' FROM ins;
DELETE FROM homepage_link_translations WHERE link_id IN (SELECT id FROM homepage_links WHERE sort_order>=10);
DELETE FROM homepage_links WHERE sort_order>=10;
WITH ins AS (INSERT INTO homepage_links (sort_order,is_active,created_at,updated_at) VALUES (10,true,now(),now()),(11,true,now(),now()),(12,true,now(),now()),(13,true,now(),now()),(14,true,now(),now()) RETURNING id,sort_order)
INSERT INTO homepage_link_translations (link_id,locale,title,url) SELECT id,'az',(CASE sort_order WHEN 10 THEN 'Valyuta məzənnələri' WHEN 11 THEN 'İnfoqrafika' WHEN 12 THEN 'İllik hesabatlar' WHEN 13 THEN 'Açıq məlumatlar' WHEN 14 THEN 'Tez-tez verilən suallar' END),(CASE sort_order WHEN 10 THEN '/az/currencies' WHEN 11 THEN '#' WHEN 12 THEN '#' WHEN 13 THEN '#' WHEN 14 THEN '#' END) FROM ins UNION ALL SELECT id,'en',(CASE sort_order WHEN 10 THEN 'Exchange rates' WHEN 11 THEN 'Infographics' WHEN 12 THEN 'Annual reports' WHEN 13 THEN 'Open data' WHEN 14 THEN 'FAQ' END),(CASE sort_order WHEN 10 THEN '/en/currencies' WHEN 11 THEN '#' WHEN 12 THEN '#' WHEN 13 THEN '#' WHEN 14 THEN '#' END) FROM ins;
DELETE FROM banner_translations WHERE banner_id IN (SELECT id FROM banners WHERE sort_order>=10);
DELETE FROM banners WHERE sort_order>=10;
WITH ins AS (INSERT INTO banners (media_id,sort_order,is_active,created_at,updated_at) VALUES (2,10,true,now(),now()),(2,11,true,now(),now()) RETURNING id,sort_order)
INSERT INTO banner_translations (banner_id,locale,title,link) SELECT id,'az',(CASE sort_order WHEN 10 THEN 'Maliyyə savadlılığı portalı' WHEN 11 THEN 'Virtual qəbul' END),'#' FROM ins UNION ALL SELECT id,'en',(CASE sort_order WHEN 10 THEN 'Financial literacy portal' WHEN 11 THEN 'Virtual reception' END),'#' FROM ins;
DELETE FROM video_translations WHERE video_id IN (SELECT id FROM videos WHERE sort_order>=10);
DELETE FROM videos WHERE sort_order>=10;
WITH ins AS (INSERT INTO videos (youtube_url,published_at,sort_order,is_active,created_at,updated_at) VALUES ('https://www.youtube.com/watch?v=dQw4w9WgXcQ','2026-06-01',10,true,now(),now()),('https://www.youtube.com/watch?v=dQw4w9WgXcQ','2026-06-02',11,true,now(),now()) RETURNING id,sort_order)
INSERT INTO video_translations (video_id,locale,title) SELECT id,'az',(CASE sort_order WHEN 10 THEN 'Mərkəzi Bankın təqdimatı' WHEN 11 THEN 'İqtisadi icmal' END) FROM ins UNION ALL SELECT id,'en',(CASE sort_order WHEN 10 THEN 'Central Bank presentation' WHEN 11 THEN 'Economic review' END) FROM ins;
DELETE FROM info_line_translations WHERE info_line_id IN (SELECT id FROM info_lines WHERE alias IN ('money_reserve_usd','money_base','nots_volume','nots_levels_28','nots_levels_84','nots_levels_168','nots_levels_252','bank_credit','bank_nation'));
DELETE FROM info_lines WHERE alias IN ('money_reserve_usd','money_base','nots_volume','nots_levels_28','nots_levels_84','nots_levels_168','nots_levels_252','bank_credit','bank_nation');
WITH ins AS (INSERT INTO info_lines (alias,year,sort_order,is_active,created_at,updated_at) VALUES ('money_reserve_usd',2026,20,true,now(),now()),('money_base',2026,21,true,now(),now()),('nots_volume',2026,30,true,now(),now()),('nots_levels_28',2026,31,true,now(),now()),('nots_levels_84',2026,32,true,now(),now()),('nots_levels_168',2026,33,true,now(),now()),('nots_levels_252',2026,34,true,now(),now()),('bank_credit',2026,40,true,now(),now()),('bank_nation',2026,41,true,now(),now()) RETURNING id,alias)
INSERT INTO info_line_translations (info_line_id,locale,title,value) SELECT id,'az',(CASE alias WHEN 'money_reserve_usd' THEN 'Rəsmi valyuta ehtiyatları' WHEN 'money_base' THEN 'Pul bazası' WHEN 'nots_volume' THEN 'Dövriyyədə olan notlar' WHEN 'nots_levels_28' THEN '28 gün' WHEN 'nots_levels_84' THEN '84 gün' WHEN 'nots_levels_168' THEN '168 gün' WHEN 'nots_levels_252' THEN '252 gün' WHEN 'bank_credit' THEN 'Kredit qoyuluşları' WHEN 'bank_nation' THEN 'Əmanətlər' END),(CASE alias WHEN 'money_reserve_usd' THEN '8 124,5 mln USD' WHEN 'money_base' THEN '16 320,7 mln AZN' WHEN 'nots_volume' THEN '1 250,0 mln AZN' WHEN 'nots_levels_28' THEN '7,15%' WHEN 'nots_levels_84' THEN '7,05%' WHEN 'nots_levels_168' THEN '6,95%' WHEN 'nots_levels_252' THEN '6,85%' WHEN 'bank_credit' THEN '24 510,3 mln AZN' WHEN 'bank_nation' THEN '12 905,8 mln AZN' END) FROM ins UNION ALL SELECT id,'en',(CASE alias WHEN 'money_reserve_usd' THEN 'Official FX reserves' WHEN 'money_base' THEN 'Money base' WHEN 'nots_volume' THEN 'Notes in circulation' WHEN 'nots_levels_28' THEN '28 days' WHEN 'nots_levels_84' THEN '84 days' WHEN 'nots_levels_168' THEN '168 days' WHEN 'nots_levels_252' THEN '252 days' WHEN 'bank_credit' THEN 'Credit investments' WHEN 'bank_nation' THEN 'Deposits' END),(CASE alias WHEN 'money_reserve_usd' THEN '8,124.5 mln USD' WHEN 'money_base' THEN '16,320.7 mln AZN' WHEN 'nots_volume' THEN '1,250.0 mln AZN' WHEN 'nots_levels_28' THEN '7.15%' WHEN 'nots_levels_84' THEN '7.05%' WHEN 'nots_levels_168' THEN '6.95%' WHEN 'nots_levels_252' THEN '6.85%' WHEN 'bank_credit' THEN '24,510.3 mln AZN' WHEN 'bank_nation' THEN '12,905.8 mln AZN' END) FROM ins;
COMMIT;
